import{_ as e,c as t,o as n,ah as r}from"./chunks/framework.BxT5r71R.js";const s=JSON.parse('{"title":"记录MAZZEL的成长：为什么不刻意追求娱乐效果","titleTemplate":"Management 2 本篇","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/Management2/PART2/4_记录MAZZEL的成长：为什么不刻意追求娱乐效果.md","filePath":"zh-cn/Management2/PART2/4_记录MAZZEL的成长：为什么不刻意追求娱乐效果.md"}'),p={name:"zh-cn/Management2/PART2/4_记录MAZZEL的成长：为什么不刻意追求娱乐效果.md"};function E(o,a,R,I,T,_){return n(),t("div",null,[...a[0]||(a[0]=[r('<p>► 2023年1月</p><h2 id="记录mazzel的成长-为什么不刻意追求娱乐效果" tabindex="-1">记录MAZZEL的成长：为什么不刻意追求娱乐效果 <a class="header-anchor" href="#记录mazzel的成长-为什么不刻意追求娱乐效果" aria-label="Permalink to &quot;记录MAZZEL的成长：为什么不刻意追求娱乐效果&quot;">​</a></h2><p>#新项目 #Mx2 #MAZZEL</p><h3 id="这次我们想做的-是一部不刻意追求娱乐效果、真正如实记录的节目。" tabindex="-1">“这次我们想做的，是一部不刻意追求娱乐效果、真正如实记录的节目。” <a class="header-anchor" href="#这次我们想做的-是一部不刻意追求娱乐效果、真正如实记录的节目。" aria-label="Permalink to &quot;“这次我们想做的，是一部不刻意追求娱乐效果、真正如实记录的节目。”&quot;">​</a></h3><p><strong>SKY-HI领导的BMSG推出了第二支男子唱跳组合MAZZEL。选秀纪录节目《MISSIONx2》（读作“Mission Mission”，以下简称《Mx2》）记录了这支组合的诞生过程，目前正在BMSG YouTube官方频道播出。1月播出的内容先从BMSG旗下练习生（trainee）RAN，以及最终选择了另一条道路的REIKO讲起，随后又出人意料地揭晓了2名未曾公开的练习生——SEITO和KAIRYU，4人的故事由此展开。首先，我们请SKY-HI谈了谈曾在《THE FIRST》第三轮评审中止步的KAIRYU。</strong></p><p>我在节目里也说过，参加过《THE FIRST》的KAIRYU在选秀结束后，给公司发来了一封邮件。他积极练习舞蹈，弥补自己在这方面的不足，还发来了基础练习的视频。我当时就想：“这孩子说不定真能有所成就。”那时，我们正想组建第二支组合，刚开始招募练习生。</p><p>我原本就想：“KAIRYU要是也能来当练习生就好了。”但毕竟在《THE FIRST》中，是我们出于自身的考虑，没有将他列为出道候选人，也不好厚着脸皮再请他过来。不过，既然他主动联系了我们，我便大约在BE:FIRST出道前给他打了一次电话，谈起组建第二支组合的构想。我说：“即使选你成为出道成员，也至少是半年以后的事，可能还得等上一年。这样你也愿意和我们一起做吗？”结果转眼间，他就从关西来到东京了（笑）。</p><p>在《THE FIRST》期间，我判断他还来不及达到BE:FIRST的出道要求。开始做《Mx2》后，我仍然觉得当时的判断没错。所以我觉得，《Mx2》也是属于KAIRYU的节目。当然，如今他比当时又成长了许多，唱歌时，声音通过麦克风传出来的效果也特别好。了解他当时表现的观众，应该会看得很有兴趣。</p><p><strong>另一位此前未曾公开的练习生是SEITO。他曾签约经纪公司，以演唱组合成员的身份活动。虽然未能报名参加《THE FIRST》，但他终于在《Mx2》中等来了充分施展的机会，并赢得了以MAZZEL成员身份出道的资格。</strong></p><p>大约从2017年起，我开始觉得：“我还什么都没做到。只能自己成立公司、自己办选秀了。”SEITO就是促使我产生这个想法的人之一。他喜欢音乐，有很多想做的事，加入男子组合也是其中之一。但真正成为组合成员后，他却常常无法如愿开展活动。那时，他会找我商量，向我倾诉烦恼。他的困境与我过去的经历很相似，我也就把他的事当成了自己的事。</p><p><strong>一般的选秀节目大多围绕成员的选拔过程展开，通过参赛者的努力与内心挣扎引发观众共鸣。第一集就公布出道成员的做法并不常见。《Mx2》却以此为起点，以纪录片的形式，按时间顺序呈现他们一路走来的历程。之所以采用这种结构，源于SKY-HI制作《THE FIRST》时的一番体会。</strong></p><h3 id="避免-神格化-呈现-变化" tabindex="-1">避免“神格化”，呈现“变化” <a class="header-anchor" href="#避免-神格化-呈现-变化" aria-label="Permalink to &quot;避免“神格化”，呈现“变化”&quot;">​</a></h3><p>很多选秀节目看着看着，就能从剪辑等方面大致猜出最终会有哪些人入选。不过，在《THE FIRST》中，我自认为尽量呈现了真实的情况，也没有刻意区别对待参赛者在镜头中的呈现。话虽如此，我们在严格评审的同时，多少也会考虑“怎样吸引观众的兴趣”“怎样增强节目的娱乐性”。</p><p>这次，我们想连这些考虑也去掉，做一部不刻意追求娱乐效果、真正如实记录的节目。做过《THE FIRST》后，我发现，即使如实呈现，也有利有弊。比如，节目展现了落选者的高光时刻，以及他们为人处世中美好的一面，观众对落选结果的议论就可能更强烈。从节目角度看，这些议论未必全是坏事，但作为作出选择的人，我心里多少还是有些复杂。</p><p>1998年法国世界杯，King Kazu（三浦知良）未能入选日本国家队名单。我想，直到现在，我心里仍有些将他神格化的倾向。类似这种“King Kazu现象”，我觉得在《THE FIRST》最终评审中落选的RAN和REIKO，也容易成为人们神格化的对象。这有好的一面，也有不好的一面。那份“缺憾”固然能衬托出一个人的美好，但他们还年轻，今后的心态和想法都会不断变化。所以我觉得，《Mx2》采用现在这种形式比较好：一开始就交代哪些人最终会留下，再呈现他们的心路历程。</p><h3 id="为什么要求mazzel具备自主成长的能力" tabindex="-1">为什么要求MAZZEL具备自主成长的能力 <a class="header-anchor" href="#为什么要求mazzel具备自主成长的能力" aria-label="Permalink to &quot;为什么要求MAZZEL具备自主成长的能力&quot;">​</a></h3><p><strong>RAN、REIKO、SEITO、KAIRYU4人的第一个任务，是组成模拟组合，挑战指定曲目。为什么把这项任务放在最前面？</strong></p><p>这次，公司所处的阶段与《THE FIRST》时不同，我没办法再像当时那样，和他们一起住在集训营里。所以，我最重视的是创造一个有利于他们自主成长的环境，也就是由他们自主思考、自主行动，不断进步。我认为，人的成长大致有两种方式：一种是在外界引导下成长，另一种是主动成长。对MAZZEL来说，能够做到后者，是最基本的条件。</p><p>BE:FIRST虽然已经积累了不少成绩，但现在还不是我能把他们放在一边、全身心投入MAZZEL的时候。恰恰相反，考虑到BE:FIRST今后的发展，我认为2023年和2024年非常关键。正因如此，MAZZEL必须具备自主成长的能力，成员们也需要一起认真思考，以组合形式开展活动究竟意味着什么。</p><p>于是，我想由4名练习生组成一支临时男子组合，一起练习指定曲目。他们今后可能要一起活动10年、20年，共同走过相当长的一段时间，其间想必会体会到各种好处与难处。SEITO已经有组合活动的经验，另外3人也能通过这次实践，切身体会组合活动，逐渐建立起作为组合成员的自觉。</p><p>当然，《Mx2》作为选秀节目越受欢迎，我就越高兴。但更重要的是，从这里诞生的MAZZEL要成为一支优秀的组合。随着节目推进，大家也会逐渐看到，RAN、REIKO、SEITO、KAIRYU各自都有需要认真面对的问题。毕竟，一旦作为MAZZEL成员出道，他们就无法回头了。</p><p>我也确实特别希望RAN和REIKO能在同一支组合里活动。但重要的不是这一点，而是大家作为组合成员活动时，都能感到幸福。而且，今后数十年一起活动，无论组合还是个人，都需要不断成长。我觉得，《Mx2》所记录的，正是他们为了这样的未来，现在该做些什么。我自己也特别期待他们今后的发展。</p><h3 id="为了ran和reiko" tabindex="-1">为了RAN和REIKO <a class="header-anchor" href="#为了ran和reiko" aria-label="Permalink to &quot;为了RAN和REIKO&quot;">​</a></h3><p><strong>节目接下来也将呈现REIKO的选择，以及他最终没有加入MAZZEL的经过。</strong></p><p>十几岁后半段设想过的事，到现在还在坚持的，其实不多吧？我自己也是这样，人多少总会发生一些变化。考虑到这一点，我当时确实觉得，REIKO既可能选择组合活动，也可能选择个人发展。如果只是想唱歌、跳舞，其实不一定非要加入组合。我想说的，在《THE FIRST》最后一集里都说了：2021年的那个时候，REIKO才刚刚形成作为艺人的自我意识。我觉得RAN也处于相近的状态。他们需要更具体地想象，自己作为艺人会如何活动。现在想来，组建模拟组合，或许尤其是为了RAN和REIKO。只有实际组队，哪怕只是模拟，他们才能更具体地想象自己作为男子组合成员活动的样子。</p><p>想到这里，我就觉得，演艺培训学校确实很了不起。接受过这类培训的孩子，已经对组合活动有了概念，又能看到前辈们如何活动，自然更容易想象自己的未来。但BMSG成立不久，对RAN和REIKO来说，即便是BE:FIRST，也终究是朋友，而不是前辈。我觉得，这样也有这样的好处。</p>',26)])])}const A=e(p,[["render",E]]);export{s as __pageData,A as default};
